<script>
 import {onMount,onDestroy} from 'svelte';import {page} from '$app/stores';import {goto} from '$app/navigation';import {listDatabaseServers,listDatabases,listLogs,listBackups,deleteDatabaseServer,installDatabaseServer,listDatabaseServerRoles,mutateDatabaseServerRole,startDatabaseServer,stopDatabaseServer} from '$lib/api.js';import {notify} from '$lib/stores.js';import Button from '$lib/components/Button.svelte';import StatusDot from '$lib/components/StatusDot.svelte';
 const tabs=['Overview','Databases','Users & Roles','Resources','Logs','Backups','Configuration','Security'];
 let active='Overview',server=null,databases=[],logs=[],backups=[],roles=[],rolesLoading=false,rolesError='',loading=true,busy=false,installing=false,serverActionBusy=false,poller=null,roleName='',rolePassword='',roleMutationBusy=false;
 async function loadRoles(){if(!server||server.engine!=='postgresql'||server.status!=='ready'){roles=[];rolesLoading=false;return}rolesLoading=true;rolesError='';const r=await listDatabaseServerRoles(server.id);if(r.ok)roles=r.data?.roles||[];else{roles=[];rolesError=r.error||'Could not load PostgreSQL roles'}rolesLoading=false}
 async function load(){const [s,d,l,b]=await Promise.all([listDatabaseServers(),listDatabases(),listLogs(100),listBackups()]);if(!s.ok){notify(s.error||'Database Server not found','error');goto('/databases');return}server=(s.data.servers||[]).find(x=>String(x.id)===$page.params.id);if(!server){notify('Database Server not found','error');goto('/databases');return}databases=(d.data?.databases||[]).filter(x=>x.server_id===server.id);logs=(l.data?.logs||[]).filter(x=>String(x.details?.server_id||'')===String(server.id));backups=(b.data?.backups||[]).filter(x=>x.resource_type==='database_server'&&String(x.resource_id)===String(server.id));await loadRoles();loading=false}
 function stopPolling(){if(poller){clearInterval(poller);poller=null}}
 function startPolling(){if(poller)return;poller=setInterval(async()=>{const result=await listDatabaseServers();if(!result.ok)return;const latest=(result.data.servers||[]).find(x=>String(x.id)===$page.params.id);if(!latest)return;server=latest;if(latest.status!=='installing'){stopPolling();notify(latest.status==='ready'?'PostgreSQL installed and verified':'PostgreSQL installation failed',latest.status==='ready'?'success':'error');}},3000)}
 onMount(async()=>{await load();if(server?.status==='installing')startPolling()});
 onDestroy(stopPolling);
 async function install(){if(!server||server.engine!=='postgresql'||installing)return;installing=true;const r=await installDatabaseServer(server.id);installing=false;if(r.ok){server={...server,status:'installing'};notify('PostgreSQL installation started on the Android device','success');startPolling()}else{notify(r.error||'Не удалось запустить установку','error');await load()}}
 async function remove(){if(!confirm('Удалить конфигурацию сервера? Базы должны быть предварительно удалены. Файлы на устройстве не затрагиваются.'))return;busy=true;const r=await deleteDatabaseServer(server.id);busy=false;if(r.ok){notify('Конфигурация удалена','success');goto('/databases')}else notify(r.error||'Не удалось удалить','error')}
 async function serverAction(action){if(!server||serverActionBusy)return;if(action==='stop'&&!confirm('Остановить PostgreSQL? Активные подключения будут завершены, незавершённые транзакции откатятся.'))return;serverActionBusy=true;const r=action==='start'?await startDatabaseServer(server.id):await stopDatabaseServer(server.id);serverActionBusy=false;if(r.ok){notify(action==='start'?'PostgreSQL запущен':'PostgreSQL остановлен','success');await load()}else notify(r.error||'Не удалось выполнить действие','error')}
 function val(v){return v===null||v===undefined||v===''?'—':v}
 async function roleMutation(action,name,password=''){if(roleMutationBusy)return;if(action==='drop'&&!confirm('Удалить роль '+name+'? PostgreSQL отклонит удаление при наличии зависимостей.'))return;roleMutationBusy=true;const r=await mutateDatabaseServerRole(server.id,action,name,password);roleMutationBusy=false;if(r.ok){notify(action==='create'?'PostgreSQL role created':'PostgreSQL role dropped','success');roleName='';rolePassword='';await loadRoles()}else notify(r.error||'Role operation failed','error')}
</script>
{#if loading}<div class="empty">Загрузка Database Server…</div>{:else if server}
<div class="page-header"><div><button class="back" on:click={()=>goto('/databases')}>← Databases</button><div class="eyebrow">DATABASE SERVER</div><h1 class="page-title">{server.name}</h1><p class="page-desc">{server.engine} · Device #{server.device_id} · Port {server.port}</p></div><div class="header-actions"><span class="state"><StatusDot status={server.status==='ready'?'online':'offline'}/>{server.status}</span>{#if (server.status==='planned'||server.status==='error')&&server.engine==='postgresql'}<Button variant="primary" on:click={install} loading={installing}>{server.status==='error'?'Retry installation':'Install PostgreSQL'}</Button>{/if}{#if server.status==='ready'&&server.engine==='postgresql'}<Button variant="danger" on:click={()=>serverAction('stop')} loading={serverActionBusy}>Stop PostgreSQL</Button>{/if}{#if server.status==='stopped'&&server.engine==='postgresql'}<Button variant="primary" on:click={()=>serverAction('start')} loading={serverActionBusy}>Start PostgreSQL</Button>{/if}{#if server.status==='planned'||server.status==='error'||server.status==='stopped'}<Button variant="danger" on:click={remove} loading={busy}>Remove configuration</Button>{/if}</div></div>
<div class="tabbar">{#each tabs as tab}<button class:active={active===tab} on:click={()=>active=tab}>{tab}</button>{/each}</div>
{#if active==='Overview'}
<div class="stats"><div><small>Status</small><strong>{server.status}</strong></div><div><small>Databases</small><strong>{databases.length}</strong></div><div><small>Engine</small><strong>{server.engine}</strong></div><div><small>Port</small><strong>{server.port}</strong></div></div>
<section class="panel"><h2>Server configuration</h2><dl><div><dt>Device</dt><dd>Android Host #{server.device_id}</dd></div><div><dt>Version</dt><dd>{val(server.version)}</dd></div><div><dt>Data directory</dt><dd class="mono">{server.data_directory}</dd></div><div><dt>Network access</dt><dd>{server.network_access}</dd></div><div><dt>Created</dt><dd>{new Date(server.created_at).toLocaleString()}</dd></div></dl></section>
{#if server.status==='planned'||server.status==='error'}<div class="notice warning">Configuration is saved but PostgreSQL is not running yet. Install PostgreSQL to run the typed Agent workflow. Existing non-empty data directories are never overwritten.</div>{:else if server.status==='installing'}<div class="notice warning">Installation is running on the Android device. This page updates automatically when the Agent reports success or failure.</div>{:else if server.status==='stopped'}<div class="notice warning">PostgreSQL is stopped. Database files remain on the device; start the server to restore database connections.</div>{/if}
{:else if active==='Databases'}
<section class="panel"><h2>Databases on this server</h2>{#if databases.length}{#each databases as d}<div class="resource"><strong>{d.name}</strong><small>{d.status}</small></div>{/each}{:else}<p class="muted">Database records will appear after the server lifecycle Agent is implemented and the server is Ready.</p>{/if}</section>
{:else if active==='Users & Roles'}
<section class="panel">
<div class="section-heading"><div><h2>PostgreSQL roles</h2><p class="muted">Live roles on this Android host. Create LOGIN roles or drop unused roles.</p></div><Button size="sm" on:click={loadRoles} loading={rolesLoading} disabled={rolesLoading||server.status!=='ready'}>↻ Refresh</Button></div>
{#if server.status!=='ready'}<p class="muted">Install and verify PostgreSQL before managing roles.</p>
{:else if rolesLoading}<p class="muted">Reading roles from PostgreSQL…</p>
{:else if rolesError}<div class="notice warning">{rolesError}</div>
{:else}
<form class="role-create" on:submit|preventDefault={()=>roleMutation('create',roleName,rolePassword)}>
<label>Role name<input bind:value={roleName} required minlength="1" maxlength="63" pattern="[A-Za-z][A-Za-z0-9_]*" placeholder="app_user"/></label>
<label>Password<input bind:value={rolePassword} required minlength="12" maxlength="256" type="password" autocomplete="new-password" placeholder="At least 12 characters"/></label>
<Button size="sm" variant="primary" loading={roleMutationBusy} disabled={roleMutationBusy}>Create LOGIN role</Button>
</form>
{#if roles.length}
<div class="role-list">{#each roles as role (role.name)}
<div class="role-row"><div class="role-name"><strong>{role.name}</strong><small>{role.can_login?'Can log in':'NOLOGIN'} · {role.inherit?'INHERIT':'NOINHERIT'}</small></div>
<div class="role-flags">{#if role.is_superuser}<span class="flag danger">SUPERUSER</span>{/if}{#if role.is_replication}<span class="flag">REPLICATION</span>{/if}{#if role.bypass_rls}<span class="flag warning">BYPASS RLS</span>{/if}<span class="connections">Limit: {role.connection_limit===-1?'∞':role.connection_limit}</span>{#if role.name!=='postgres'&&!role.name.startsWith('pg_')}<Button size="sm" variant="danger" disabled={roleMutationBusy} on:click={()=>roleMutation('drop',role.name)}>Drop</Button>{/if}</div></div>
{/each}</div>
{:else}<p class="muted">No non-system roles were returned by PostgreSQL.</p>{/if}
{/if}
</section>
{:else if active==='Resources'}
<section class="panel"><h2>Resource budget</h2><dl><div><dt>RAM budget</dt><dd>{server.ram_budget_mb?server.ram_budget_mb+' MB':'Auto'}</dd></div><div><dt>Storage allocation</dt><dd>{server.storage_limit_gb==='unlimited'?'Unlimited':server.storage_limit_gb+' GB'}</dd></div><div><dt>Maximum connections</dt><dd>{server.max_connections}</dd></div><div><dt>Storage monitoring</dt><dd>{server.monitor_storage?'Enabled':'Disabled'}</dd></div></dl></section>
{:else if active==='Logs'}
<section class="panel"><h2>Database Server activity</h2><p class="muted">Control Plane events associated with this server. PostgreSQL engine logs require a separate agent log-stream feature.</p>{#if logs.length}{#each logs as entry}<div class="resource"><strong>{entry.action.replaceAll('_',' ')}</strong><small>{new Date(entry.created_at).toLocaleString()} · {JSON.stringify(entry.details||{})}</small></div>{/each}{:else}<p class="muted">No recorded events for this server yet.</p>{/if}<a href="/logs">Open all activity logs</a></section>
{:else if active==='Backups'}
<section class="panel"><h2>Server backups</h2>{#if backups.length}{#each backups as b}<div class="resource"><strong>{b.file_name}</strong><small>{b.status}</small></div>{/each}{:else}<p class="muted">No database-server backups have been created.</p>{/if}</section>
{:else if active==='Configuration'}
<section class="panel"><h2>Configuration</h2><dl><div><dt>Bind address</dt><dd>{server.bind_address}</dd></div><div><dt>SSL mode</dt><dd>{server.ssl_mode}</dd></div><div><dt>Authentication</dt><dd>{server.auth_method}</dd></div><div><dt>Auto-start</dt><dd>{server.auto_start?'Enabled':'Disabled'}</dd></div><div><dt>Process policy</dt><dd>{server.process_policy}</dd></div></dl><p class="muted">Changes are read-only until safe Agent configuration and rollback commands are available. RAM/storage budgets, auto-start and process policy are saved as preferences; enforcement is not active yet.</p></section>
{:else}
<section class="panel"><h2>Security</h2><dl><div><dt>Bind address</dt><dd>127.0.0.1</dd></div><div><dt>Remote access</dt><dd>Disabled</dd></div><div><dt>SSL / TLS</dt><dd>{server.ssl_mode}</dd></div><div><dt>Secrets</dt><dd>None stored</dd></div></dl><p class="muted">Remote database access is blocked. The current PostgreSQL install binds to localhost; TLS transport configuration and encrypted application credentials are not yet provisioned.</p></section>
{/if}
{/if}
<style>
.back{border:0;background:none;color:#a5b4fc;font-size:10px;margin-bottom:10px}.eyebrow{font-size:9px;letter-spacing:.14em;color:#818cf8;font-weight:700;margin:5px 0}.header-actions{display:flex;align-items:center;gap:12px}.state{display:flex;align-items:center;gap:7px;font-size:10px;color:#94a3b8}.tabbar{display:flex;gap:4px;overflow:auto;border-bottom:1px solid #253149;margin-bottom:14px}.tabbar button{white-space:nowrap;padding:10px 12px;border:0;border-bottom:2px solid transparent;background:none;color:#64748b;font-size:10px}.tabbar button.active{color:#c7d2fe;border-bottom-color:#6366f1}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin-bottom:12px}.stats>div{display:grid;gap:7px;padding:13px;background:#101727;border:1px solid #253149;border-radius:10px}.stats small{font-size:9px;color:#64748b}.stats strong{font-size:17px}.panel{padding:16px;background:#101727;border:1px solid #253149;border-radius:11px;margin-bottom:12px}.panel h2{font-size:12px;margin-bottom:13px}.panel p,.muted{font-size:10px;color:#64748b;line-height:1.6}.panel dl{display:grid;gap:9px}.panel dl div{display:flex;justify-content:space-between;gap:15px;font-size:10px}.panel dt{color:#64748b}.panel dd{color:#cbd5e1;text-align:right;overflow-wrap:anywhere}.mono{font-family:monospace}.notice{padding:12px;border-radius:9px;font-size:10px;line-height:1.6}.notice.warning{background:#2b2112;border:1px solid #70501e;color:#fcd58a}.section-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:12px}.section-heading h2{margin-bottom:5px}.role-create{display:flex;align-items:end;gap:10px;flex-wrap:wrap;padding:12px 0;border-bottom:1px solid #253149;margin-bottom:12px}.role-create label{display:grid;gap:5px;color:#94a3b8;font-size:10px}.role-create input{background:#0b1120;border:1px solid #334155;border-radius:7px;color:#e2e8f0;padding:9px;font-size:11px;min-width:150px}.role-list{border-top:1px solid #253149}.role-row{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:11px 0;border-bottom:1px solid #253149}.role-name{display:grid;gap:4px;min-width:0}.role-name strong{font-size:10px;overflow-wrap:anywhere}.role-name small,.connections{font-size:9px;color:#64748b}.role-flags{display:flex;justify-content:flex-end;align-items:center;gap:6px;flex-wrap:wrap}.flag{font-size:8px;padding:4px 6px;border:1px solid #334155;border-radius:5px;color:#cbd5e1}.flag.danger{border-color:#7f1d1d;color:#fca5a5}.flag.warning{border-color:#854d0e;color:#fcd34d}.resource{display:flex;justify-content:space-between;padding:10px 0;border-top:1px solid #253149;font-size:10px}.resource small{color:#64748b}
@media(max-width:650px){.stats{grid-template-columns:repeat(2,1fr)}.header-actions{align-items:flex-end;flex-direction:column}}
</style>